def grant_existing_admins(apps, schema_editor):
    """Creators who are still members become admins. Otherwise the earliest member does.

    Open-join circles from before this policy had no admin flag. A circle with no
    members is left alone.
    """
    Circle = apps.get_model("prayers", "Circle")
    CircleMembership = apps.get_model("prayers", "CircleMembership")
    for circle in Circle.objects.all().iterator():
        if circle.created_by_id:
            CircleMembership.objects.filter(
                circle_id=circle.id, user_id=circle.created_by_id
            ).update(is_admin=True)
        if not CircleMembership.objects.filter(circle_id=circle.id, is_admin=True).exists():
            earliest = (
                CircleMembership.objects.filter(circle_id=circle.id)
                .order_by("joined_at", "id")
                .first()
            )
            if earliest is not None:
                earliest.is_admin = True
                earliest.save(update_fields=["is_admin"])


